const pageScript = `<script>
document.querySelectorAll('[data-copy-target]').forEach(function(button){button.addEventListener('click',function(){var source=document.getElementById(button.dataset.copyTarget);if(!source||!navigator.clipboard)return;navigator.clipboard.writeText(source.textContent.trim()).then(function(){var old=button.textContent;button.textContent='已复制';setTimeout(function(){button.textContent=old},1600)})})});
document.querySelectorAll('[data-key-copy]').forEach(function(form){form.addEventListener('submit',async function(event){
  event.preventDefault();
  var button=form.querySelector('button');
  if(!navigator.clipboard){alert('当前浏览器不支持复制到剪贴板');return;}
  button.disabled=true;
  try{
    var response=await fetch(form.action,{method:'POST',body:new URLSearchParams(new FormData(form)),credentials:'same-origin',headers:{Accept:'application/json'}});
    if(!response.ok)throw new Error('无法读取密钥，请刷新页面后重试');
    var result=await response.json();
    await navigator.clipboard.writeText(result.key);
    button.textContent='已复制';
    setTimeout(function(){button.textContent='复制密钥'},1600);
  }catch(error){alert(error.message||'复制失败，请重试');}
  finally{button.disabled=false;}
})});
</script>`

const loginTemplate = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 · CPA Companion</title>` + pageStyle + `</head><body><div class="login-shell"><div class="login-brand"><div class="login-brand-top"><img class="brand-mark" src="/assets/logo.png" width="30" height="30" alt=""><span>CPA Companion</span></div><div class="login-wordmark" aria-hidden="true"><span>CPA.</span><span>YOUR.</span><span>WAY.</span></div><div class="login-brand-foot">为每位成员提供独立的 API 访问入口。</div></div><main class="login-panel"><div class="login-box"><div class="login-logo" aria-hidden="true"><img src="/assets/logo.png" width="62" height="62" alt=""></div><h1>登录附属服务</h1><p>使用 Linux DO 账号登录，管理你的 API Key，并通过管理员指定的上游账号调用模型。</p><a class="button" href="/auth/login">使用 Linux DO 登录</a><div class="login-hint">登录后，你可以查看分配的账号、创建或撤销自己的密钥。</div></div><div class="login-panel-foot">CPA Companion · OAuth2 安全登录</div></main></div></body></html>`
